// internal-task phase 3: the custody identity is generated by scripts/sealed/keygen.ts with no person handling a key.
//
// Value: protects=keygen creates the identity file exclusively (0600 in a 0700 directory), refuses to replace one, writes
// the escrow under the passphrase derived from UBICLOUD_API_KEY, checks both derive the recipient, writes
// sealed/recipient.txt and prints only the recipient and its fingerprint; --check-escrow fails loudly when UBICLOUD_API_KEY
// was rotated without --re-escrow or the drive copy is missing; --re-escrow replaces the escrow on the custody branch in
// one validated, non-force commit after the new escrow decrypts, keeping the old one in history, and refuses with
// HE-SEALED-013 and pushes nothing when the repository is not private (asked of a stand-in gh); --restore recovers the
// drive copy from the escrow; fails_when=the identity or the environment value reaches stdout, stderr or argv, a second
// keygen overwrites the first, a stale escrow passes the check, or the escrow cannot be recovered; why_new=keygen and the
// escrow modes are new; seam=the CLI as a subprocess with throwaway UBICLOUD_API_KEY values, temp paths and a throwaway
// bare repository with a custody branch; no_claim=the drive's own durability.
import { afterAll, expect, test } from 'bun:test';
import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync, rmSync, statSync, unlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { identityToRecipient } from 'age-encryption';
import { decryptWith, encryptTo, sha256 } from '../runner/heldout/sealed.ts';
import { decryptEscrow, escrowPassphrase, identityFromText } from '../scripts/sealed/identity.ts';
import { initCustodyClone, readAccessLog, validateCustodyChange } from '../scripts/sealed/custody.ts';
import { fakeGh } from './sealed-fixture.ts';

const ROOT = join(import.meta.dir, '..');
const tmp = mkdtempSync(join(tmpdir(), 'he-keygen-'));
afterAll(() => rmSync(tmp, { recursive: true, force: true }));
const ENV_VALUE = 'throwaway-ubicloud-value-for-the-keygen-test';

test('keygen creates the identity and escrow exclusively and refuses a second run; the escrow check, re-escrow after a key rotation and restore work on the custody branch', async () => {
  const repo = join(tmp, 'repo');
  const identity = join(tmp, 'drive', 'custody', 'identity.age-key');
  const escrow = join(tmp, 'escrow', 'identity.age');
  const env = { PATH: process.env.PATH, HOME: process.env.HOME, UBICLOUD_API_KEY: ENV_VALUE };
  const run = () => spawnSync('bun', [join(ROOT, 'scripts', 'sealed', 'keygen.ts'), '--identity', identity, '--escrow', escrow, '--repo', repo], { encoding: 'utf8', env });
  const r = run();
  expect(r.status, r.stderr).toBe(0);
  const recipient = readFileSync(join(repo, 'sealed', 'recipient.txt'), 'utf8').trim();
  expect(recipient).toMatch(/^age1[0-9a-z]+$/);
  expect(r.stdout).toBe(`recipient ${recipient}\nfingerprint sha256 ${sha256(recipient)}\n`);
  expect(r.stderr).toBe('');
  const text = readFileSync(identity, 'utf8');
  const key = text.split('\n').find((l) => l.startsWith('AGE-SECRET-KEY-1'))!;
  expect(await identityToRecipient(key)).toBe(recipient);
  expect(text).toContain(`# public key: ${recipient}`);
  expect(statSync(identity).mode & 0o777).toBe(0o600);
  expect(statSync(join(tmp, 'drive', 'custody')).mode & 0o777).toBe(0o700);
  expect(statSync(escrow).mode & 0o777).toBe(0o600);
  expect(readFileSync(escrow).toString('latin1')).not.toContain('AGE-SECRET-KEY');
  expect(readFileSync(escrow).subarray(0, 21).toString()).toBe('age-encryption.org/v1');
  for (const out of [r.stdout, r.stderr]) { expect(out).not.toContain('AGE-SECRET-KEY'); expect(out).not.toContain(key.slice(16)); expect(out).not.toContain(escrowPassphrase(ENV_VALUE)); expect(out).not.toContain(ENV_VALUE); }
  // a second run refuses and changes nothing
  const again = run();
  expect(again.status).toBe(2);
  expect(again.stderr).toContain('already exists');
  expect(again.stderr).not.toContain('AGE-SECRET-KEY');
  expect(readFileSync(identity, 'utf8')).toBe(text);
  // recipient.txt naming a recipient also refuses, before anything is written
  const other = spawnSync('bun', [join(ROOT, 'scripts', 'sealed', 'keygen.ts'), '--identity', join(tmp, 'other', 'k'), '--repo', repo], { encoding: 'utf8', env });
  expect(other.status).toBe(2);
  expect(other.stderr).toContain('already names a recipient');
  expect(existsSync(join(tmp, 'other', 'k'))).toBe(false);
  // --escrow without the environment value refuses before anything is written
  const noEnv = spawnSync('bun', [join(ROOT, 'scripts', 'sealed', 'keygen.ts'), '--identity', join(tmp, 'noenv', 'k'), '--escrow', join(tmp, 'noenv', 'e'), '--repo', join(tmp, 'repo2')], { encoding: 'utf8', env: { PATH: process.env.PATH, HOME: process.env.HOME } });
  expect(noEnv.status).toBe(2);
  expect(noEnv.stderr).toContain('UBICLOUD_API_KEY');
  expect(existsSync(join(tmp, 'noenv', 'k'))).toBe(false);

  // the escrow modes work on the custody branch: a throwaway bare repository whose orphan custody branch holds the escrow
  const bare = join(tmp, 'origin.git');
  const g = (cwd: string, ...a: string[]) => execFileSync('git', a, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  execFileSync('git', ['init', '-q', '--bare', bare]);
  const seed = join(tmp, 'custody-seed');
  execFileSync('git', ['init', '-q', '-b', 'custody', seed]);
  g(seed, 'config', 'user.email', 'keygen-test@example.invalid'); g(seed, 'config', 'user.name', 'keygen test');
  writeFileSync(join(seed, 'README.md'), 'synthetic custody branch\n');
  execFileSync('mkdir', ['-p', join(seed, 'escrow')]);
  writeFileSync(join(seed, 'escrow', 'identity.age'), readFileSync(escrow));
  g(seed, 'add', '-A'); g(seed, 'commit', '-q', '-m', 'custody: escrow'); g(seed, 'push', '-q', bare, 'HEAD:refs/heads/custody');
  g(repo, 'init', '-q'); g(repo, 'remote', 'add', 'origin', bare);
  const clone = join(tmp, 'custody');
  initCustodyClone(clone, bare, repo);
  g(clone, 'config', 'user.email', 'keygen-test@example.invalid'); g(clone, 'config', 'user.name', 'keygen test');
  const ROTATED = 'a-rotated-throwaway-ubicloud-value';
  const ghPrivate = fakeGh(join(tmp, 'gh-bin'), 'true'), ghPublic = fakeGh(join(tmp, 'gh-bin'), 'false');
  const mode = (m: string, value: string | undefined, gh = ghPrivate) => spawnSync('bun', [join(ROOT, 'scripts', 'sealed', 'keygen.ts'), m, '--identity', identity, '--custody', clone, '--repo', repo, '--gh', gh], { encoding: 'utf8', env: { PATH: process.env.PATH, HOME: process.env.HOME, ...(value ? { UBICLOUD_API_KEY: value } : {}) } });
  const clean = (r: { stdout: string; stderr: string }) => { for (const out of [r.stdout, r.stderr]) { expect(out).not.toContain('AGE-SECRET-KEY-1' + key.slice(16, 24)); expect(out).not.toContain(ENV_VALUE); expect(out).not.toContain(ROTATED); expect(out).not.toContain(escrowPassphrase(ENV_VALUE)); expect(out).not.toContain(escrowPassphrase(ROTATED)); } };

  const ok = mode('--check-escrow', ENV_VALUE);
  expect(ok.status, ok.stderr).toBe(0);
  expect(ok.stdout).toMatch(/^ESCROW: ok; the drive copy and the escrow at refs\/heads\/custody [0-9a-f]{12} derive the recipient in sealed\/recipient.txt \(fingerprint sha256 [0-9a-f]{12}\)\n$/);
  clean(ok);
  // UBICLOUD_API_KEY rotated but not re-escrowed: the check fails loudly and names the fix
  const stale = mode('--check-escrow', ROTATED);
  expect(stale.status).toBe(2);
  expect(stale.stderr).toContain('HE-SEALED-012 the escrow');
  expect(stale.stderr).toContain('keygen.ts --re-escrow');
  clean(stale);
  expect(mode('--check-escrow', undefined).stderr).toContain('HE-SEALED-012 UBICLOUD_API_KEY is not set');
  // re-escrow under the rotated value: one custody commit replacing the escrow, the old one kept in history
  const before = g(clone, 'rev-parse', 'HEAD');
  // ...but not while the repository is public: HE-SEALED-013, exit 2, nothing pushed
  const exposed = mode('--re-escrow', ROTATED, ghPublic);
  expect(exposed.status).toBe(2);
  expect(exposed.stderr).toContain('HE-SEALED-013');
  expect(exposed.stdout).toBe('');
  clean(exposed);
  expect(g(bare, 'rev-parse', 'refs/heads/custody')).toBe(before);
  const re = mode('--re-escrow', ROTATED);
  expect(re.status, re.stderr).toBe(0);
  expect(re.stdout).toMatch(/^ESCROW: re-escrowed under the current UBICLOUD_API_KEY in [0-9a-f]{12} on refs\/heads\/custody/);
  clean(re);
  const view = join(tmp, 'custody-view');
  initCustodyClone(view, bare, repo);
  expect(g(view, 'diff', '--name-status', before, 'HEAD').split('\n').sort()).toEqual(['A\taccess-log.jsonl', 'M\tescrow/identity.age']);
  expect(readAccessLog(view).map((e) => e.event)).toEqual(['escrowed']);
  expect(validateCustodyChange(view, before)).toEqual([]);
  const old = execFileSync('git', ['cat-file', 'blob', `${before}:escrow/identity.age`], { cwd: view });
  expect(identityFromText(await decryptEscrow(new Uint8Array(old), ENV_VALUE, 'old escrow'), 'old escrow')).toBe(key);
  expect(mode('--check-escrow', ROTATED).status).toBe(0);
  expect(mode('--check-escrow', ENV_VALUE).status).toBe(2);
  const current = mode('--re-escrow', ROTATED);
  expect(current.stdout).toContain('nothing pushed');

  // recovery rehearsal: the drive copy is gone; the check says so, --restore recreates it from the escrow, and the
  // restored identity decrypts a synthetic ciphertext sealed to the recipient
  const ciphertext = await encryptTo(recipient, new TextEncoder().encode('synthetic sealed bundle'));
  unlinkSync(identity);
  const lost = mode('--check-escrow', ROTATED);
  expect(lost.status).toBe(2);
  expect(lost.stderr).toContain('keygen.ts --restore');
  expect(mode('--re-escrow', ROTATED).stderr).toContain('is missing');
  expect(mode('--restore', ENV_VALUE).status).toBe(2);
  expect(existsSync(identity)).toBe(false);
  const restored = mode('--restore', ROTATED);
  expect(restored.status, restored.stderr).toBe(0);
  clean(restored);
  expect(readFileSync(identity, 'utf8')).toBe(text);
  expect(new TextDecoder().decode(await decryptWith(identityFromText(readFileSync(identity, 'utf8'), identity), ciphertext))).toBe('synthetic sealed bundle');
  expect(mode('--restore', ROTATED).stderr).toContain('exists; --restore only recreates a missing drive copy');
  expect(mode('--check-escrow', ROTATED).status).toBe(0);
}, 240_000);
